{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "10",
      "explanation": "The SOQL query is constructed using string concatenation, which can lead to SOQL injection if the searchKey is not properly sanitized.",
      "remediation": "Use parameterized queries or escape the searchKey to prevent SOQL injection."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS violation on Opportunity.Amount",
      "severity": "Medium",
      "file": "OpportunityStageService.cls",
      "lines": "10",
      "explanation": "The code updates the Opportunity.Amount field without enforcing Field-Level Security (FLS) checks.",
      "remediation": "Remove the Amount field from the SOQL query or enforce FLS checks before updating the field."
    },
    {
      "category": "C4",
      "title": "Excessive permissions in permission set",
      "severity": "Medium",
      "file": "Opportunity_Stage_Editor.permissionset-meta.xml",
      "lines": "N/A",
      "explanation": "The permission set allows read access to Opportunity.Amount, which is not necessary for the intended purpose.",
      "remediation": "Remove the read permission for Opportunity.Amount from the permission set."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS not enforced on Lead.Status",
      "severity": "Medium",
      "file": "LeadQualifierService.cls",
      "lines": "10",
      "explanation": "The code updates the 'Status' field on a Lead without enforcing Field-Level Security (FLS). This could allow users to set the status to any value, bypassing FLS checks.",
      "remediation": "Use the Schema.SObjectType.Lead.fields.Status.isUpdateable() method to enforce FLS before updating the field."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in permission set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions elements",
      "explanation": "The permission set grants excessive permissions such as 'ModifyAllData' and 'ViewAllData', which are not necessary for tier-1 support agents.",
      "remediation": "Remove unnecessary permissions such as 'ModifyAllData' and 'ViewAllData' from the permission set."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Missing Sharing Enforcement",
      "severity": "Medium",
      "file": "ContactSearchController.cls",
      "lines": "1-6",
      "explanation": "The class is declared without sharing, which means it will bypass the sharing rules and FLS checks, potentially exposing data to users who should not have access.",
      "remediation": "Add the sharing enforcement by removing 'without sharing' from the class declaration or explicitly enforce sharing rules within the class."
    },
    {
      "category": "C4",
      "title": "Excessive Profile Permissions",
      "severity": "Medium",
      "file": "Partner Site Profile.profile-meta.xml",
      "lines": "N/A",
      "explanation": "The profile allows read access to the Contact object and its fields, which is more permissive than necessary for a guest user profile.",
      "remediation": "Revise the profile permissions to only allow necessary read access to the Contact object and its fields for guest users."
    }
  ]
}
